-- mdt_report_templates
UPDATE `mdt_report_templates` SET `name` = 'Incidente Padrão', `content` = '<h2>Resumo do incidente</h2>\n<p>Em [DATE], aproximadamente às [TIME] horas, [OFFICER NAME/BADGE] respondeu a uma chamada em [LOCATION] sobre [TYPE OF INCIDENT].</p>\n\n<h2>Detalhes do incidente</h2>\n<p>Na chegada, os policiais observaram [DESCRIBE SCENE]. [DESCRIBE WHAT HAPPENED IN CHRONOLOGICAL ORDER].</p>\n\n<h2>Partes Envolvidas</h2>\n<p><strong>Parte Denunciante:</strong> [NAME] - [CONTACT INFO]</p>\n<p><strong>Suspeito(s):</strong> [NAME/DESCRIPTION]</p>\n<p><strong>Vítima(s):</strong> [NAME]</p>\n<p><strong>Testemunha(s):</strong> [NAME - STATEMENT SUMMARY]</p>\n\n<h2>Evidência Coletado</h2>\n<ul>\n<li>[ITEM 1 - DESCRIPTION AND LOCATION FOUND]</li>\n<li>[ITEM 2 - DESCRIPTION AND LOCATION FOUND]</li>\n</ul>\n\n<h2>Ações tomadas</h2>\n<p>[DESCRIBE OFFICER ACTIONS: ARRESTS MADE, CITATIONS ISSUED, MEDICAL ATTENTION PROVIDED, ETC.]</p>\n\n<h2>Conclusão</h2>\n<p>[CASE STATUS: OPEN/CLOSED/PENDING INVESTIGATION]. [ANY FOLLOW-UP REQUIRED].</p>' WHERE `name` = 'Standard Incident' AND `type` = 'Incident Report' AND `content` = '<h2>Incident Summary</h2>\n<p>On [DATE] at approximately [TIME] hours, [OFFICER NAME/BADGE] responded to a call at [LOCATION] regarding [TYPE OF INCIDENT].</p>\n\n<h2>Details of Incident</h2>\n<p>Upon arrival, officers observed [DESCRIBE SCENE]. [DESCRIBE WHAT HAPPENED IN CHRONOLOGICAL ORDER].</p>\n\n<h2>Parties Involved</h2>\n<p><strong>Reporting Party:</strong> [NAME] - [CONTACT INFO]</p>\n<p><strong>Suspect(s):</strong> [NAME/DESCRIPTION]</p>\n<p><strong>Victim(s):</strong> [NAME]</p>\n<p><strong>Witness(es):</strong> [NAME - STATEMENT SUMMARY]</p>\n\n<h2>Evidence Collected</h2>\n<ul>\n<li>[ITEM 1 - DESCRIPTION AND LOCATION FOUND]</li>\n<li>[ITEM 2 - DESCRIPTION AND LOCATION FOUND]</li>\n</ul>\n\n<h2>Actions Taken</h2>\n<p>[DESCRIBE OFFICER ACTIONS: ARRESTS MADE, CITATIONS ISSUED, MEDICAL ATTENTION PROVIDED, ETC.]</p>\n\n<h2>Conclusion</h2>\n<p>[CASE STATUS: OPEN/CLOSED/PENDING INVESTIGATION]. [ANY FOLLOW-UP REQUIRED].</p>';
UPDATE `mdt_report_templates` SET `name` = 'Tráfego padrão', `content` = '<h2>Resumo de incidente de trânsito</h2>\n<p>Em [DATE] aproximadamente às [TIME] horas, [OFFICER NAME/BADGE] respondeu a um incidente de trânsito em [LOCATION/INTERSECTION].</p>\n\n<h2>Informações do veículo</h2>\n<p><strong>Veículo 1:</strong> [YEAR MAKE MODEL COLOR] - Placa: [PLATE] - Driver: [NAME]</p>\n<p><strong>Veículo 2:</strong> [YEAR MAKE MODEL COLOR] - Placa: [PLATE] - Driver: [NAME]</p>\n\n<h2>Descrição do Incidente</h2>\n<p>[DESCRIBE HOW THE INCIDENT OCCURRED. INCLUDE DIRECTION OF TRAVEL, SPEED, ROAD CONDITIONS, WEATHER.]</p>\n\n<h2>Lesões</h2>\n<p>[DESCRIBE ANY INJURIES. NOTE IF EMS WAS CALLED AND TRANSPORT DESTINATION.]</p>\n\n<h2>Citações emitidas</h2>\n<ul>\n<li>[DRIVER NAME] - [VIOLATION CODE] - [DESCRIPTION]</li>\n</ul>\n\n<h2>Declarações de testemunhas</h2>\n<p>[NAME]: [BRIEF SUMMARY OF STATEMENT]</p>\n\n<h2>Diagrama / Adicional Notas</h2>\n<p>[DESCRIBE SCENE LAYOUT OR REFERENCE ATTACHED DIAGRAM]</p>' WHERE `name` = 'Standard Traffic' AND `type` = 'Traffic Report' AND `content` = '<h2>Traffic Incident Summary</h2>\n<p>On [DATE] at approximately [TIME] hours, [OFFICER NAME/BADGE] responded to a traffic incident at [LOCATION/INTERSECTION].</p>\n\n<h2>Vehicle Information</h2>\n<p><strong>Vehicle 1:</strong> [YEAR MAKE MODEL COLOR] - Plate: [PLATE] - Driver: [NAME]</p>\n<p><strong>Vehicle 2:</strong> [YEAR MAKE MODEL COLOR] - Plate: [PLATE] - Driver: [NAME]</p>\n\n<h2>Incident Description</h2>\n<p>[DESCRIBE HOW THE INCIDENT OCCURRED. INCLUDE DIRECTION OF TRAVEL, SPEED, ROAD CONDITIONS, WEATHER.]</p>\n\n<h2>Injuries</h2>\n<p>[DESCRIBE ANY INJURIES. NOTE IF EMS WAS CALLED AND TRANSPORT DESTINATION.]</p>\n\n<h2>Citations Issued</h2>\n<ul>\n<li>[DRIVER NAME] - [VIOLATION CODE] - [DESCRIPTION]</li>\n</ul>\n\n<h2>Witness Statements</h2>\n<p>[NAME]: [BRIEF SUMMARY OF STATEMENT]</p>\n\n<h2>Diagram / Additional Notes</h2>\n<p>[DESCRIBE SCENE LAYOUT OR REFERENCE ATTACHED DIAGRAM]</p>';
UPDATE `mdt_report_templates` SET `name` = 'Investigação Completa', `content` = '<h2>Visão Geral do Caso</h2>\n<p><strong>Número do Caso:</strong> [CASE #]</p>\n<p><strong>Investigador Principal:</strong> [NAME/BADGE]</p>\n<p><strong>Data Aberto:</strong> [DATE]</p>\n<p><strong>Classificação:</strong> [FELONY/MISDEMEANOR/OTHER]</p>\n\n<h2>Contexto</h2>\n<p>[PROVIDE CONTEXT FOR THE INVESTIGATION. WHAT PROMPTED IT. REFERENCE ANY PRIOR REPORTS.]</p>\n\n<h2>Pessoas de Interesse</h2>\n<p><strong>Suspeito 1:</strong> [NAME] - [DESCRIPTION, KNOWN ASSOCIATES, LAST KNOWN LOCATION]</p>\n<p><strong>Suspeito 2:</strong> [NAME] - [DESCRIPTION]</p>\n\n<h2>Resumo de evidências</h2>\n<ul>\n<li>[EVIDENCE ITEM] - [WHERE/HOW OBTAINED] - [RELEVANCE]</li>\n<li>[EVIDENCE ITEM] - [WHERE/HOW OBTAINED] - [RELEVANCE]</li>\n</ul>\n\n<h2>Linha do tempo de Eventos</h2>\n<ul>\n<li><strong>[DATE/TIME]:</strong> [EVENT]</li>\n<li><strong>[DATE/TIME]:</strong> [EVENT]</li>\n</ul>\n\n<h2>Entrevistas realizadas</h2>\n<p><strong>[NAME]:</strong> [SUMMARY OF INTERVIEW]</p>\n\n<h2>Descobertas e Recomendações</h2>\n<p>[SUMMARIZE FINDINGS. RECOMMEND NEXT STEPS: CHARGES, FURTHER INVESTIGATION, CASE CLOSURE.]</p>' WHERE `name` = 'Full Investigation' AND `type` = 'Investigation Report' AND `content` = '<h2>Case Overview</h2>\n<p><strong>Case Number:</strong> [CASE #]</p>\n<p><strong>Lead Investigator:</strong> [NAME/BADGE]</p>\n<p><strong>Date Opened:</strong> [DATE]</p>\n<p><strong>Classification:</strong> [FELONY/MISDEMEANOR/OTHER]</p>\n\n<h2>Background</h2>\n<p>[PROVIDE CONTEXT FOR THE INVESTIGATION. WHAT PROMPTED IT. REFERENCE ANY PRIOR REPORTS.]</p>\n\n<h2>Persons of Interest</h2>\n<p><strong>Suspect 1:</strong> [NAME] - [DESCRIPTION, KNOWN ASSOCIATES, LAST KNOWN LOCATION]</p>\n<p><strong>Suspect 2:</strong> [NAME] - [DESCRIPTION]</p>\n\n<h2>Evidence Summary</h2>\n<ul>\n<li>[EVIDENCE ITEM] - [WHERE/HOW OBTAINED] - [RELEVANCE]</li>\n<li>[EVIDENCE ITEM] - [WHERE/HOW OBTAINED] - [RELEVANCE]</li>\n</ul>\n\n<h2>Timeline of Events</h2>\n<ul>\n<li><strong>[DATE/TIME]:</strong> [EVENT]</li>\n<li><strong>[DATE/TIME]:</strong> [EVENT]</li>\n</ul>\n\n<h2>Interviews Conducted</h2>\n<p><strong>[NAME]:</strong> [SUMMARY OF INTERVIEW]</p>\n\n<h2>Findings and Recommendations</h2>\n<p>[SUMMARIZE FINDINGS. RECOMMEND NEXT STEPS: CHARGES, FURTHER INVESTIGATION, CASE CLOSURE.]</p>';
UPDATE `mdt_report_templates` SET `name` = 'Prisão Padrão', `content` = '<h2>Resumo da prisão</h2>\n<p>Em [DATE], aproximadamente às [TIME] horas, [OFFICER NAME/BADGE] colocou [SUSPECT NAME] sob prisão em [LOCATION].</p>\n\n<h2>Suspeito Informações</h2>\n<p><strong>Nome:</strong> [FULL NAME]</p>\n<p><strong>ID do cidadão:</strong> [ID]</p>\n<p><strong>Descrição:</strong> [HEIGHT, BUILD, CLOTHING, DISTINGUISHING MARKS]</p>\n\n<h2>Causa provável</h2>\n<p>[DESCRIBE THE CIRCUMSTANCES AND EVIDENCE THAT ESTABLISHED PROBABLE CAUSE FOR THE ARREST]</p>\n\n<h2>Cargas</h2>\n<ul>\n<li>[CHARGE CODE] - [CHARGE DESCRIPTION] - [FELONY/MISDEMEANOR]</li>\n<li>[CHARGE CODE] - [CHARGE DESCRIPTION] - [FELONY/MISDEMEANOR]</li>\n</ul>\n\n<h2>Narrativa</h2>\n<p>[DETAILED CHRONOLOGICAL ACCOUNT OF EVENTS LEADING TO THE ARREST]</p>\n\n<h2>Evidências Apreendidas</h2>\n<ul>\n<li>[ITEM] - [DESCRIPTION]</li>\n</ul>\n\n<h2>Miranda Rights</h2>\n<p>O suspeito foi lido pelos direitos de Miranda em [TIME]. O suspeito [DID/DID NOT] invoca o direito a um advogado. O suspeito [DID/DID NOT] fornece uma declaração.</p>\n\n<h2>Processing</h2>\n<p>O suspeito foi autuado em [FACILITY] em [TIME]. [BAIL/HOLD INFORMATION].</p>' WHERE `name` = 'Standard Arrest' AND `type` = 'Arrest Report' AND `content` = '<h2>Arrest Summary</h2>\n<p>On [DATE] at approximately [TIME] hours, [OFFICER NAME/BADGE] placed [SUSPECT NAME] under arrest at [LOCATION].</p>\n\n<h2>Suspect Information</h2>\n<p><strong>Name:</strong> [FULL NAME]</p>\n<p><strong>Citizen ID:</strong> [ID]</p>\n<p><strong>Description:</strong> [HEIGHT, BUILD, CLOTHING, DISTINGUISHING MARKS]</p>\n\n<h2>Probable Cause</h2>\n<p>[DESCRIBE THE CIRCUMSTANCES AND EVIDENCE THAT ESTABLISHED PROBABLE CAUSE FOR THE ARREST]</p>\n\n<h2>Charges</h2>\n<ul>\n<li>[CHARGE CODE] - [CHARGE DESCRIPTION] - [FELONY/MISDEMEANOR]</li>\n<li>[CHARGE CODE] - [CHARGE DESCRIPTION] - [FELONY/MISDEMEANOR]</li>\n</ul>\n\n<h2>Narrative</h2>\n<p>[DETAILED CHRONOLOGICAL ACCOUNT OF EVENTS LEADING TO THE ARREST]</p>\n\n<h2>Evidence Seized</h2>\n<ul>\n<li>[ITEM] - [DESCRIPTION]</li>\n</ul>\n\n<h2>Miranda Rights</h2>\n<p>Suspect was read Miranda rights at [TIME]. Suspect [DID/DID NOT] invoke right to counsel. Suspect [DID/DID NOT] provide a statement.</p>\n\n<h2>Processing</h2>\n<p>Suspect was booked at [FACILITY] at [TIME]. [BAIL/HOLD INFORMATION].</p>';
UPDATE `mdt_report_templates` SET `name` = 'Coleta de evidências', `content` = '<h2>Resumo do relatório de evidências</h2>\n<p><strong>Caso relacionado:</strong> [CASE #]</p>\n<p><strong>Oficial de coleta:</strong> [NAME/BADGE]</p>\n<p><strong>Data Coletado:</strong> [DATE]</p>\n<p><strong>Localização:</strong> [COLLECTION SITE]</p>\n\n<h2>Itens de evidência</h2>\n<h3>Item 1</h3>\n<p><strong>Descrição:</strong> [DETAILED DESCRIPTION]</p>\n<p><strong>Série/ID:</strong> [IF APPLICABLE]</p>\n<p><strong>Localização Encontrado:</strong> [EXACT LOCATION AT SCENE]</p>\n<p><strong>Condição:</strong> [CONDITION WHEN FOUND]</p>\n<p><strong>Armazenamento:</strong> [LOCKER/STASH ID]</p>\n\n<h3>Item 2</h3>\n<p><strong>Descrição:</strong> [DETAILED DESCRIPTION]</p>\n<p><strong>Local encontrado:</strong> [EXACT LOCATION AT SCENE]</p>\n<p><strong>Armazenamento:</strong> [LOCKER/STASH ID]</p>\n\n<h2>Cadeia de Custódia</h2>\n<ul>\n<li><strong>[DATE/TIME]:</strong> Coletado por [NAME] em [LOCATION]</li>\n<li><strong>[DATE/TIME]:</strong> Transferido para [NAME/FACILITY]</li>\n</ul>\n\n<h2>Análise solicitada</h2>\n<p>[DESCRIBE ANY LAB ANALYSIS OR FORENSIC TESTING REQUESTED]</p>\n\n<h2>Notas</h2>\n<p>[ANY ADDITIONAL OBSERVATIONS OR CONTEXT]</p>' WHERE `name` = 'Evidence Collection' AND `type` = 'Evidence Report' AND `content` = '<h2>Evidence Report Summary</h2>\n<p><strong>Related Case:</strong> [CASE #]</p>\n<p><strong>Collecting Officer:</strong> [NAME/BADGE]</p>\n<p><strong>Date Collected:</strong> [DATE]</p>\n<p><strong>Location:</strong> [COLLECTION SITE]</p>\n\n<h2>Evidence Items</h2>\n<h3>Item 1</h3>\n<p><strong>Description:</strong> [DETAILED DESCRIPTION]</p>\n<p><strong>Serial/ID:</strong> [IF APPLICABLE]</p>\n<p><strong>Location Found:</strong> [EXACT LOCATION AT SCENE]</p>\n<p><strong>Condition:</strong> [CONDITION WHEN FOUND]</p>\n<p><strong>Storage:</strong> [LOCKER/STASH ID]</p>\n\n<h3>Item 2</h3>\n<p><strong>Description:</strong> [DETAILED DESCRIPTION]</p>\n<p><strong>Location Found:</strong> [EXACT LOCATION AT SCENE]</p>\n<p><strong>Storage:</strong> [LOCKER/STASH ID]</p>\n\n<h2>Chain of Custody</h2>\n<ul>\n<li><strong>[DATE/TIME]:</strong> Collected by [NAME] at [LOCATION]</li>\n<li><strong>[DATE/TIME]:</strong> Transferred to [NAME/FACILITY]</li>\n</ul>\n\n<h2>Analysis Requested</h2>\n<p>[DESCRIBE ANY LAB ANALYSIS OR FORENSIC TESTING REQUESTED]</p>\n\n<h2>Notes</h2>\n<p>[ANY ADDITIONAL OBSERVATIONS OR CONTEXT]</p>';

