-- mdt_fto_phases
UPDATE `mdt_fto_phases` SET `name` = 'Fase 1 - Observação', `description` = 'O estagiário observa o FTO durante chamadas e patrulha. O FTO demonstra procedimentos adequados, redação de relatórios e comunicação por rádio.' WHERE `id` = 1 AND `job` = 'police' AND `name` = 'Phase 1 - Observation' AND `description` = 'Trainee observes the FTO during calls and patrol. FTO demonstrates proper procedures, report writing, and radio communication.';
UPDATE `mdt_fto_phases` SET `name` = 'Fase 2 – Patrulha Supervisionada', `description` = 'O estagiário lidera as chamadas com supervisão do FTO. O FTO avalia a tomada de decisões, a segurança dos oficiais e a aplicação da lei.' WHERE `id` = 2 AND `job` = 'police' AND `name` = 'Phase 2 - Supervised Patrol' AND `description` = 'Trainee takes the lead on calls with FTO supervision. FTO evaluates decision-making, officer safety, and law application.';
UPDATE `mdt_fto_phases` SET `name` = 'Fase 3 – Supervisão Reduzida', `description` = 'O estagiário opera com entrada mínima de FTO. O FTO só intervém quando necessário e avalia a prontidão para patrulha individual.' WHERE `id` = 3 AND `job` = 'police' AND `name` = 'Phase 3 - Reduced Supervision' AND `description` = 'Trainee operates with minimal FTO input. FTO only intervenes when necessary and evaluates readiness for solo patrol.';
UPDATE `mdt_fto_phases` SET `name` = 'Fase 4 – Avaliação Solo', `description` = 'O estagiário patrulha de forma independente enquanto o FTO observa à distância ou analisa relatórios. Avaliação final antes da aprovação.' WHERE `id` = 4 AND `job` = 'police' AND `name` = 'Phase 4 - Solo Evaluation' AND `description` = 'Trainee patrols independently while the FTO observes from a distance or reviews reports. Final evaluation before sign-off.';

