-- mdt_sop_settings
UPDATE `mdt_sop_settings` SET `mission_statement` = '<p><strong>Missão</strong></p><p>A missão da Aplicação da Lei é fornecer serviços de segurança pública eficientes e eficazes aos residentes e visitantes da cidade. Fornecemos esses serviços com caráter, competência e comunicação aberta.</p><p><strong>Valores</strong></p><p>Julgamento, Unidade, Habilidade, Confiança, Engenhosidade, Coragem, Empoderamento = <strong>JUSTIÇA</strong></p><p><strong>M.O.S. Requisito</strong></p><p>Todos os Membros do Serviço (MOS) devem cumprir os valores acima mencionados e o código de conduta de procedimento em todos os momentos.</p><p>Um briefing deve ser realizado se houver 4 ou mais policiais no referido departamento por seu departamento CS. A legislatura do departamento ditará os termos desses briefings.</p>', `introduction` = '<p>Ao acessar este Terminal de Dados Móvel, você reconhece que leu, compreendeu e concorda em seguir todos os Procedimentos Operacionais Padrão estabelecidos pelo Departamento.</p><p>Espera-se que todos os Membros do Serviço mantenham o profissionalismo, cumpram a lei e ajam com integridade em todos os momentos durante o serviço.</p><p>O não cumprimento desses procedimentos pode resultar em ação disciplinar, incluindo, mas não se limitando a suspensão, rebaixamento ou rescisão.</p><p>Se você tiver alguma dúvida sobre esses procedimentos, entre em contato com seu supervisor ou cadeia de comando.</p>' WHERE `job` = 'police' AND `mission_statement` = '<p><strong>Mission</strong></p><p>The mission of Law Enforcement is to provide efficient, effective, public safety services to the residents and visitors of the city. We deliver these services with character, competence, and open communication.</p><p><strong>Values</strong></p><p>Judgment, Unity, Skill, Trust, Ingenuity, Courage, Empowerment = <strong>JUSTICE</strong></p><p><strong>M.O.S. Requirement</strong></p><p>All Members of Service (M.O.S.) are expected to comply with the aforementioned values and proceeding code of conduct at all times.</p><p>A briefing must be conducted if there are 4 or more law enforcement officers in said department by their department CS. Department legislature will dictate the terms of those briefings.</p>' AND `introduction` = '<p>By accessing this Mobile Data Terminal, you acknowledge that you have read, understood, and agree to follow all Standard Operating Procedures set forth by the Department.</p><p>All Members of Service are expected to maintain professionalism, uphold the law, and act with integrity at all times while on duty.</p><p>Failure to comply with these procedures may result in disciplinary action, including but not limited to suspension, demotion, or termination.</p><p>If you have any questions regarding these procedures, contact your supervisor or chain of command.</p>';

