-- mdt_sop_sections
UPDATE `mdt_sop_sections` SET `title` = 'Código de Ética', `content` = '<p>O Código de Ética estabelece um conjunto de valores e princípios nos quais todo o trabalho do departamento deve ser realizado. A violação de qualquer Ética pode levar a reclamações e ações disciplinares que podem incluir demissão.</p><p>Ao se tornar um Oficial de Aplicação da Lei, você ganha muitas responsabilidades, incluindo o poder e a capacidade de fazer cumprir a lei. Dentro da lei, você tem muito poder para prender, acusar e revistar civis. Tudo isso deve estar dentro das leis do estado. Qualquer falha em seguir qualquer oficial de patente superior pode levar ao Comando Disciplinar. A habilidade dada aos LEOs não pode ser abusada ou usada de qualquer forma diversa, caso contrário, ações disciplinares poderão ser tomado.</p><ul><li>Profissionalismo</li><li>Responsabilidade</li><li>Respeito</li><li>Liderança</li></ul><p>Nunca agirei oficiosamente ou permitirei sentimentos pessoais, preconceitos, animosidades ou amizades para influenciar minhas decisões. Sem comprometer o crime e com acusação implacável de criminosos, aplicarei a lei de maneira cortês e apropriada, sem medo ou favor, malícia ou má vontade, nunca empregando força ou violência desnecessária e nunca aceitando gratificações.</p><p>Reconheço o distintivo do meu cargo como um símbolo de fé pública, e aceito-o como uma confiança pública a ser mantida, desde que eu seja fiel à ética do serviço policial. Me esforçarei constantemente para alcançar esses objetivos e ideais, dedicando-me diante de Deus à profissão que escolhi... aplicação da lei.</p>' WHERE `category_id` = 1 AND `title` = 'Code of Ethics' AND `content` = '<p>The Code of Ethics lays out a set of values and principles in which all work of the department should be done within. Violation of any of the Ethics may lead to complaints, disciplinary action which may include dismissal.</p><p>When becoming a Law Enforcement Officer, you gain many responsibilities including the power and the ability to enforce the law. Within the law you have a lot of power to arrest, charge, and search civilians. All of these must be within the laws of the state. Any failure to follow any superior ranking officers may lead to Command Discipline. The ability that is given to LEOs may not be abused or be used in any miscellaneous way otherwise disciplinary action may be taken.</p><ul><li>Professionalism</li><li>Responsibility</li><li>Respect</li><li>Leadership</li></ul><p>I will never act officiously or permit personal feelings, prejudices, animosities, or friendships to influence my decisions. With no compromise for crime and with relentless prosecution of criminals, I will enforce the law courteously and appropriately without fear or favor, malice or ill will, never employing unnecessary force or violence and never accepting gratuities.</p><p>I recognize the badge of my office as a symbol of public faith, and I accept it as a public trust to be held so long as I am true to the ethics of the police service. I will constantly strive to achieve these objectives and ideals, dedicating myself before God to my chosen profession... law enforcement.</p>';
UPDATE `mdt_sop_sections` SET `title` = 'Juramento de Estado', `content` = '<p><em>"Juro solenemente: apoiarei, protegerei e defenderei a Constituição e o Governo dos Estados Unidos e do Estado; prestarei estrita obediência aos meus superiores na Agência de Aplicação da Lei e observarei todas as ordens e regulamentos prescritos por eles para o governo e a administração da Patrulha; sempre me conduzirei com sobriedade, honra e honestidade; manterei atenção rigorosa, pontual e constante aos meus deveres; absterei-me de qualquer conduta ofensiva ou incompatível com um agente da lei; desempenharei minhas funções sem medo, com imparcialidade e a devida cortesia; e cumprirei bem e fielmente os deveres do cargo que agora assumo. Que Deus me ajude."</em></p>' WHERE `category_id` = 2 AND `title` = 'Oath of State' AND `content` = '<p><em>"I do solemnly swear: I will support, protect and defend the Constitution and Government of the United States and of the State; I will render strict obedience to my superiors in the Law Enforcement Agency, and observe and abide by all orders and regulations prescribed by them for the government and administration of said Patrol; I will always conduct myself soberly, honorably and honestly; I will maintain strict, punctual and constant attention to my duties; I will abstain from all offensive personality or conduct unbecoming a Law Enforcement Officer; I will perform my duties fearlessly, impartially and with all due courtesy and I will well and faithfully perform the duties of a Law Enforcement Officer on which I am now about to enter. So help me God."</em></p>';
UPDATE `mdt_sop_sections` SET `title` = 'Equipamento e prontidão', `content` = '<ul><li><strong>Os agentes da lei devem ter todos os equipamentos adequados para desempenhar as funções policiais.</strong></li><li><strong>Os agentes da lei devem ter todos os equipamentos em condições de uso e prontos para uso.</strong></li><li><strong>Os agentes da lei devem garantir que o veículo tenha as devidas equipamento e pode ser reparado.</strong></li><li><strong>Os agentes da lei devem garantir que todas as armas estejam carregadas e em condições de uso.</strong></li><li><strong>Os agentes da lei devem comparecer a todos os TODOS CHAMADAS.</strong></li><li><strong>Os agentes da lei seguirão a cadeia de comando adequada.</strong></li><li><strong>Os agentes da lei devem garantir que agem de maneira segura.</strong></li></ul>' WHERE `category_id` = 3 AND `title` = 'Equipment and Readiness' AND `content` = '<ul><li><strong>Law Enforcement Officers must have all proper equipment to carry out police duties.</strong></li><li><strong>Law Enforcement Officers must have all equipment serviceable and ready for use.</strong></li><li><strong>Law Enforcement Officers must ensure the vehicle has proper equipment and is serviceable.</strong></li><li><strong>Law Enforcement Officers must ensure all weapons are loaded and serviceable.</strong></li><li><strong>Law Enforcement Officers must attend any ALL CALLS.</strong></li><li><strong>Law Enforcement Officers will follow the proper chain of command.</strong></li><li><strong>Law Enforcement Officers must ensure that they act in a safe manner.</strong></li></ul>';
UPDATE `mdt_sop_sections` SET `title` = 'Padrões de Conduta dos Oficiais', `content` = '<ul><li>Os Policiais devem manter uma postura profissional em todos os momentos.</li><li>Os Policiais nunca devem assediar, intimidar ou de outra forma infringir os direitos de qualquer civil.</li><li>Os Policiais nunca devem abusar de seu poder para beneficiar a si mesmos ou prejudicar outras pessoas de qualquer forma. (Financeiramente, fisicamente, verbalmente ou de qualquer forma que esteja abaixo do juramento de um Oficial de proteger e servir.)</li><li>Os Policiais devem ajudar qualquer civil necessitado com o melhor de sua capacidade.</li><li>Os Policiais devem obedecer a qualquer ordem legal emitida por um supervisor de posto acima do seu.</li><li>Lei Os Policiais são responsáveis por qualquer dano que causarem a uma pessoa fora do estado de direito e de acordo com o guia de patrulha de cada departamento.</li><li>Os Policiais devem e irão seguir todas as leis rodoviárias e não abusar das sirenes para ignorar essas leis.</li><li>Os Policiais devem ser capazes de justificar qualquer uso de força ou causa para uma prisão/parada de qualquer pessoa.</li><li>Os policiais não discriminarão qualquer pessoa por qualquer motivo, incluindo, mas não se limitando a: raça, religião, orientação sexual e gênero.</li></ul>' WHERE `category_id` = 4 AND `title` = 'Officer Conduct Standards' AND `content` = '<ul><li>Law Enforcement Officers are to maintain professional bearings at all times.</li><li>Law Enforcement Officers are to never harass, intimidate or otherwise infringe on any civilian''s rights.</li><li>Law Enforcement Officers are to never abuse their power to benefit themselves or hurt others in any way. (Financially, physically, verbally or in any way that is below that of an Officer''s oath to protect and serve.)</li><li>Law Enforcement Officers must aid any civilian in need to the best of his/her ability.</li><li>Law Enforcement Officers must obey any lawful order issued by a supervisor of rank above theirs.</li><li>Law Enforcement Officers are responsible for any harm he/she causes to a person outside the rule of law and in accordance with each department''s patrol guide.</li><li>Law Enforcement Officers must and will follow all road laws and not abuse sirens to ignore these laws.</li><li>Law Enforcement Officers must be able to justify any use of force or cause for an arrest/stop of any person.</li><li>Law Enforcement Officers will not discriminate against any person for any reason including but not limited to: Race, religion, sexual orientation and gender.</li></ul>';
UPDATE `mdt_sop_sections` SET `title` = 'Disciplinas de Comando', `content` = '<p>Disciplinas de Comando são recomendadas para má conduta que é mais problemática do que treinamento inadequado, mas não chega ao nível de cobrança. As disciplinas de comando serão emitidas para todos os policiais que infringirem os regulamentos ou não obedecerem a uma ordem legal de um supervisor, também conhecida como insubordinação.</p><p>Os policiais podem acumular até <strong>(3)</strong> Disciplinas de comando antes de serem demitidos do departamento. Os encarregados da aplicação da lei também podem ser demitidos dependendo do nível da infração ou infrações cometidas; isso cabe ao estado-maior de comando e é aprovado pelo Comissário.</p><p><strong>Nota:</strong> Um Verbal e Escrito devido à repetição da mesma má conduta será igual a um FINAL.</p><p>(Verbal, Escrito, Final) são os CDs a que se referem.</p>' WHERE `category_id` = 5 AND `title` = 'Command Disciplines' AND `content` = '<p>Command Disciplines are recommended for misconduct that is more problematic than poor training, but does not rise to the level of charges. Command disciplines will be issued to all Law Enforcement Officers who break regulations or fail to obey a lawful order from a supervisor, also known as insubordination.</p><p>Law Enforcement Officers can accumulate up to <strong>(3)</strong> Command Disciplines prior to termination from the department. Law Enforcement Officers may be terminated also depending on the level of the offense or offenses committed; this is up to the command staff and approved by the Commissioner.</p><p><strong>Note:</strong> A Verbal and Written due to repeating the same misconduct will be equal to a FINAL.</p><p>(Verbal, Written, Final) are what CDs are referred to.</p>';
UPDATE `mdt_sop_sections` SET `title` = 'Suspensão e Rescisão', `content` = '<p>Os Policiais estão sujeitos à suspensão em qualquer CD escrito com base no critério do supervisor.</p><p>A rescisão é a resposta final aos problemas de comportamento de um Policial. Os dirigentes serão formalmente demitidos pelo departamento e isso será decidido pelo supervisor. Oficiais Probatórios, ainda em situação de acompanhamento, podem ser demitidos por um SGT/LT.</p>' WHERE `category_id` = 5 AND `title` = 'Suspension and Termination' AND `content` = '<p>Law Enforcement Officers are subject to suspension on any written CD based on the supervisor''s discretion.</p><p>Termination is the final response to a Law Enforcement Officer''s issues with behavior. Officers will formally be let go by the department and this is decided by the supervisor. Probationary Officers, still on ride along status, can be terminated by a SGT/LT.</p>';
UPDATE `mdt_sop_sections` SET `title` = 'Regras e Presença', `content` = '<p><strong>Regras:</strong> Todas as regras, políticas e procedimentos se aplicam aos LEOs em todos os momentos.</p><p><strong>Política de Presença:</strong> Os Policiais que estão ativos são muito apreciados, mas como todos sabemos, nossas vidas e família são mais importantes. Os policiais que estarão ocupados devem notificar a equipe de comando.</p><p><strong>Conduta proibida:</strong></p><ul><li>Qualquer consumo de narcóticos e/ou álcool durante o serviço = TERMINAÇÃO</li><li>Envolver-se em discussão com outros membros enquanto estiver embriagado IRL em uma patrulha canal.</li></ul>' WHERE `category_id` = 5 AND `title` = 'Rules and Attendance' AND `content` = '<p><strong>Rules:</strong> All rules, policies and procedures apply to LEOs at all times.</p><p><strong>Attendance Policy:</strong> Law Enforcement Officers who are active are much appreciated but as we all know our lives and family are more important. Law Enforcement Officers who will be busy must notify the command staff.</p><p><strong>Prohibited Conduct:</strong></p><ul><li>Any consumption of narcotics and or alcohol while on duty = TERMINATION</li><li>Engaging in discussion with other members while intoxicated IRL in a patrol channel.</li></ul>';
UPDATE `mdt_sop_sections` SET `title` = 'Direito a um Supervisor', `content` = '<p>Os membros do público têm o direito de falar com um supervisor. Quando um supervisor é solicitado por um civil, espera-se que ele responda à chamada quando estiver disponível.</p><p>Os detidos também têm o direito de falar com um supervisor, se o solicitarem. Se um supervisor for solicitado por um suspeito que está sendo preso, ele poderá ser levado ao Departamento de Polícia ou ao local ativo atual para aguardar por um. <strong>Mas, eles não devem receber nenhuma acusação criminal até que o supervisor tenha falado com eles.</strong></p><p><strong>O direito a um supervisor só pode ser recusado nas seguintes situações:</strong></p><ul><li>O Supervisor esteve anteriormente envolvido no caso do suspeito e confirmou que o suspeito será acusado.</li><li>Se o policial que fez a prisão já for um Supervisor. Por exemplo, o sargento não precisa solicitar que um tenente ou outro supervisor fale com seu suspeito se o suspeito solicitar.</li><li>Não há supervisores disponíveis.</li><li>Se não houver supervisores de plantão, qualquer FTA pode assumir o papel do supervisor e falar com o suspeito como assistente de treinamento de campo.</li></ul>' WHERE `category_id` = 6 AND `title` = 'Right to a Supervisor' AND `content` = '<p>Members of the public have the right to speak with a supervisor. When a supervisor is requested by a civilian, they are expected to respond to the call when they are available.</p><p>Detainees also have the right to speak with a supervisor if they requested one. If a supervisor is requested by a suspect being arrested then they may be brought to the Police Department or to the current active scene to wait for one. <strong>But, they must not receive any criminal charges until the supervisor has spoken to them.</strong></p><p><strong>The right to a supervisor can only be declined in the following situations:</strong></p><ul><li>The Supervisor was previously involved in the suspect''s case and has confirmed the suspect is to be charged.</li><li>If the arresting officer is already a Supervisor. For example, the Sergeant does not have to request a Lieutenant or another supervisor to talk to his/her suspect if the suspect requests it.</li><li>There are no supervisors available.</li><li>If there are no supervisors on Duty, any FTA can take the supervisor''s role and talk to the Suspect as a Field Training Assistant.</li></ul>';
UPDATE `mdt_sop_sections` SET `title` = 'Recebendo e respondendo a chamadas', `content` = '<p><strong>Recebendo uma chamada de emergência:</strong> Sempre confirme a chamada, se for enviada por despacho, avise e esclareça que você está respondendo. Se notificado pelo sistema 911, informe a todos sobre o Canal de Tráfego de Rádio ao qual você estará respondendo.</p><p><strong>Chegando ao local:</strong> Quando você chegar ao local, alerte o despacho e seus colegas de que você chegou ao local. Geralmente, a menos que seja designado, o primeiro oficial no local será sempre o Oficial Responsável (OIC). O primeiro Supervisor na cena assumirá o comando da cena. É sua responsabilidade manter o despachante e/ou outros policiais informados sobre o desenrolar da situação e levar quaisquer suspeitos de volta à Delegacia.</p>' WHERE `category_id` = 6 AND `title` = 'Receiving and Responding to Calls' AND `content` = '<p><strong>Receiving an Emergency Call:</strong> Always acknowledge the call, if sent by dispatch, notify them and clarify that you are responding. If notified by the 911 system, then let everyone know of the Radio Traffic Channel that you will be responding to.</p><p><strong>Arriving On The Scene:</strong> When you have arrived on the scene, alert dispatch and your colleagues that you have arrived on the scene. Generally, unless designated, the first officer on the scene will always be the Officer in Charge (OIC). The first Supervisor on the scene will take scene command. It is their responsibility to keep dispatch and/or other officers informed of the situation unfolding and getting any suspects back to the Police Station.</p>';
UPDATE `mdt_sop_sections` SET `title` = 'Prisão e Castigo', `content` = '<p><strong>Tratamento de Suspeitos:</strong> Se um supervisor for solicitado por um suspeito que está sendo preso, ele poderá ser levado ao Departamento de Polícia para esperar por um, mas não deverá receber nenhuma acusação criminal até que o supervisor tenha falado com ele. Consulte Direito a um Supervisor para saber quando o direito a um supervisor pode ser negado.</p><p><strong>Punições:</strong> Espera-se que os oficiais não somem leis e não maximizem as sentenças, a menos que o assunto seja Crime. Violações menores de leis (por exemplo, infrações de trânsito) devem <strong>NUNCA</strong> ser somadas para criar uma sentença de prisão maior. Geralmente, a extensão ou cooperação oferecida pelo suspeito deve ser considerada ao estabelecer uma sentença de prisão ou emitir uma multa.</p><ul><li><strong>O oficial que prendeu DEVE ler os Direitos de Miranda</strong> antes de prender ou transportar o sujeito para a Delegacia. *Em diferentes circunstâncias, os direitos de Miranda podem ser lidos na delegacia.</li><li>Os policiais que prendem devem explicar a(s) acusação(ões) do suspeito antes de prendê-los.</li><li>Os policiais devem tirar as algemas do suspeito antes de enviá-lo para a prisão.</li><li>Ao transportar um suspeito, o veículo deve incluir uma gaiola de transporte prisional nele.</li><li>O(s) suspeito(s) devem ser revistados antes de serem transportados.</li><li>Os agentes de detenção devem escrever um relatório de detenção no sistema MDT.</li><li><strong>Ao prender um suspeito, o agente de detenção deve sempre usar os códigos penais para as sentenças e para o Acusações.</strong></li></ul><p>Todas as sentenças estão sujeitas ao critério do oficial após levar em consideração outros crimes pendentes, status de liberdade condicional, reincidência ou outras informações obtidas durante a investigação. Os policiais são incentivados a dar clemência a criminosos cooperativos e não violentos. Todas as acusações são acumuláveis ​​e sujeitas a alterações sem aviso prévio.</p><p><strong>Classificação de Crimes:</strong></p><ul><li><strong>Infração</strong> - Violação menos grave do código penal. Resulta em multa e/ou perda de privilégio.</li><li><strong>Contravenção</strong> - Violação menor do código penal. Resulta em prisão, multa e/ou pena de prisão.</li><li><strong>Crime grave</strong> - Violação grave do código penal. Resulta em prisão, multa e pena de prisão.</li></ul>' WHERE `category_id` = 6 AND `title` = 'Jail and Punishment' AND `content` = '<p><strong>Handling of Suspects:</strong> If a supervisor is requested by a suspect being arrested then they may be brought to the Police Department to wait for one but they must not receive any criminal charges until the supervisor has spoken to them. Please refer to Right to a Supervisor for when the right to a supervisor can be denied.</p><p><strong>Punishments:</strong> Officers are expected to not add up laws and not maximize the sentences unless the subject is Felony. Minor breakage of laws (for example, Traffic Offences) should <strong>NEVER</strong> be added up to create a larger jail sentence. Generally, the extent or cooperation offered by the suspect should be considered when setting a jail sentence or issuing a fine.</p><ul><li><strong>Arresting officer MUST read the Miranda Rights</strong> before arresting or transporting the subject to the Station. *In different circumstances Miranda rights may be read at the station.</li><li>Arresting Officers have to explain the suspect''s charge(s) before jailing them.</li><li>Officers must uncuff the suspect before sending them to Jail.</li><li>When transporting a suspect, the vehicle must include a Prison Transport Cage in it.</li><li>The suspect(s) must be searched before they get transported.</li><li>Arresting Officers must write an Arrest Report on the MDT system.</li><li><strong>When arresting a suspect, the Arresting Officer must always use the Penal Codes for the Sentences and for the Charges.</strong></li></ul><p>All sentencing is subject to officer discretion after taking into consideration other pending crimes, probation status, repeat offenses, or other information obtained during the investigation. Officers are encouraged to give leniency to cooperative, non-violent criminals. All charges are stackable and subject to change without notice.</p><p><strong>Classification of Crimes:</strong></p><ul><li><strong>Infraction</strong> - Least serious violation of the penal code. Results in a fine and/or loss of a privilege.</li><li><strong>Misdemeanor</strong> - Minor violation of the penal code. Results in arrest, a fine and/or jail time.</li><li><strong>Felony</strong> - Serious violation of the penal code. Results in arrest, a fine and jail time.</li></ul>';
UPDATE `mdt_sop_sections` SET `title` = 'Definições de condução de emergência', `content` = '<p><strong>Condução de emergência (sem perseguição):</strong> Operação de um veículo de emergência, com luzes vermelhas e azuis e sirene acionadas, por um agente da lei em resposta a uma situação de risco à vida ou a um crime violento em andamento, observando a segurança de terceiros.</p><p><strong>Condução em perseguição:</strong> Tentativa de um agente da lei, operando um veículo de emergência com luzes e sirene acionadas, de abordar os ocupantes de outro veículo em movimento quando o condutor em fuga está ciente da tentativa e resiste à abordagem mantendo ou aumentando a velocidade, desobedecendo às leis de trânsito ou tentando escapar.</p><p>Os agentes devem manter distância segura do veículo suspeito durante a perseguição para permitir frenagens de emergência. A manobra PIT só pode ser realizada por supervisores ou agentes certificados, sem trânsito próximo e fora de áreas residenciais.</p><p><strong>Acompanhamento:</strong> Condução próxima a um veículo de interesse sem empregar meios de abordagem, como luzes, sirene ou outra ordem de parada.</p>' WHERE `category_id` = 7 AND `title` = 'Emergency Driving Definitions' AND `content` = '<p><strong>Emergency Driving (Non-Pursuit):</strong> The operation of an emergency vehicle (emergency red and blue lights and siren in operation) by a Law Enforcement Officer in response to a life-threatening situation or a violent crime in progress, using due regard for the safety of others.</p><p><strong>Pursuit Driving:</strong> An attempt by a Law Enforcement Officer operating an emergency vehicle and simultaneously utilizing Red and Blue Lights and siren to apprehend an occupant(s) of another moving vehicle, when the driver of the fleeing vehicle is aware of the attempt and is resisting apprehension by maintaining or increasing speed, disobeying Traffic Laws, ignoring or attempting to elude Law Enforcement Officers.</p><p>Officer(s) always must leave space between the suspect and their car during the Pursuit, in case of emergency braking or accidents. Pit Maneuver can only be performed by Supervisors or Pit Certified Officers. Pit Maneuver should only be performed if there is no traffic. Pit Maneuver should never be performed in Residential Areas.</p><p><strong>Following:</strong> Driving in close proximity to a subject vehicle without using any apprehension efforts, such as red and blue lights or sirens, or any other method of direction to stop.</p>';
UPDATE `mdt_sop_sections` SET `title` = 'Códigos de resposta', `content` = '<p><strong>Códigos de resposta de chamada de emergência:</strong></p><p><strong>Código 1 - Não urgente / sem luzes, sem sirenes:</strong> Chamadas de supervisor, danos à propriedade, invasão, roubo de propriedade (não em andamento), Travessia irregular.</p><p><strong>Código 2 - Alta prioridade / Luzes acesas, sem sirenes:</strong> Chamadas de parada de trânsito, briga em andamento, acidentes de carro, tiros disparados na área, roubo de propriedade em andamento.</p><p><strong>Código 3 - Emergência / Luzes e sirenes ligadas:</strong> Perseguição de veículo, policial caído ou em perigo, assalto à mão armada, pessoa procurada, atualização de crime, Atirador ativo.</p>' WHERE `category_id` = 7 AND `title` = 'Response Codes' AND `content` = '<p><strong>Emergency Call Response Codes:</strong></p><p><strong>Code 1 - Non-Urgent / No Lights, No Sirens:</strong> Supervisor Calls, Damage to property, Trespassing, Theft of property (not in progress), Jaywalking.</p><p><strong>Code 2 - High Priority / Lights On, No Sirens:</strong> Traffic Stop calls, Fight in Progress, Car Accidents, Shots Fired in the Area, Theft of Property in progress.</p><p><strong>Code 3 - Emergency / Lights and Sirens On:</strong> Vehicle Pursuit, Officer Down or in distress, Armed Robbery, Wanted Person, Felony Upgrade, Active Shooting.</p>';
UPDATE `mdt_sop_sections` SET `title` = 'Identificação de Diretores', `content` = '<p>Espera-se sempre que os policiais se identifiquem como policiais durante uma situação e especialmente ao entrar em um prédio ou durante paradas de trânsito. Caso contrário, os oficiais poderiam ser confundidos com pessoas hostis. Os policiais também devem informar seu nome e números de crachá a outras pessoas, se solicitado, se a pessoa que os solicita desejar fazer uma reclamação.</p><p><em>*Oficiais disfarçados não são obrigados a se identificar para civis se estiverem conduzindo uma investigação.</em></p>' WHERE `category_id` = 8 AND `title` = 'Identification of Officers' AND `content` = '<p>Officers are always expected to identify themselves as law enforcement officers during a situation and especially when entering a building or during Traffic Stops. Otherwise the officers could be mistaken as hostile persons. Officers must also report their name and badge numbers to others if requested, if the person requesting them wishes to make a complaint.</p><p><em>*Undercover officers are not obligated to identify themselves to Civilians if they are running an Investigation.</em></p>';
UPDATE `mdt_sop_sections` SET `title` = 'Desempenho de Funções', `content` = '<p><strong>Desempenho negligente de funções:</strong> Um oficial que desempenha funções, mesmo dentro dos limites da lei, pode ser considerado negligente no desempenho de suas funções se obviamente não agir da melhor maneira possível ou se seu comportamento colocar injustificadamente em perigo a vida de cidadãos, de outros oficiais ou de si mesmo e os riscos superarem óbvia e fortemente os benefícios.</p><p><strong>Respostas do supervisor às chamadas:</strong> Espera-se que os supervisores respondam à chamada mais importante no momento e não podem ficar ociosos ou ignorar o policiamento regular e as tarefas de supervisão em preferência a tarefas mais servis. <strong>Os supervisores devem responder e julgar todos os incidentes de tiroteio envolvendo policiais.</strong></p><ul><li>Os supervisores devem fazer relatórios de incidentes (no MDT) de cenas envolvidas em tiroteios, acidentes com oficiais, perseguições com veículos.</li></ul>' WHERE `category_id` = 8 AND `title` = 'Performance of Duties' AND `content` = '<p><strong>Negligent Performance of Duties:</strong> An officer performing duties, even within the limits of the law, may be found negligent in the performance of his or her duties if they obviously do not act to the best of their ability or if their behavior unreasonably endangers the lives of citizens, other officers, or themselves and the risks obviously and heavily outweigh the benefits.</p><p><strong>Supervisor Responses to Calls:</strong> Supervisors are expected to respond to the most important call at the time and may not stay idle or ignore regular policing and supervising duties in preference of more menial tasks. <strong>Supervisors must respond to and judge all officer-involved shooting incidents.</strong></p><ul><li>Supervisors must take Incident Reports (on MDT) of Shooting Involved Scenes, Officer Accidents, Vehicle Pursuits.</li></ul>';
UPDATE `mdt_sop_sections` SET `title` = 'Estrutura do Mandado', `content` = '<p>Para que um mandado seja motivo suficiente para prender alguém e seja classificado como "válido", você precisa fornecer uma visão geral da situação, incluindo evidências e armas utilizadas (se houver). Mandados que digam apenas “Tentativa de atropelar o motorista do uber” não serão classificados como “válidos” nem serão suficientes para prender alguém, pois não fornecem uma visão geral da situação nem nos dizem que tipo de evidência estava presente no momento. Também é importante especificar se se trata de um mandado de busca ou de prisão.</p><p>Um bom exemplo de mandado de prisão é: <em>"Mandado de prisão: Atirou e matou um civil durante o assalto à mão armada em Sandy 24 horas por dia, 7 dias por semana, com uma Beretta M9. Várias testemunhas, incluindo policiais, testemunharam a situação. Evidências encontradas no local."</em></p><p>A um bom exemplo de mandado de busca e apreensão é: <em> "Mandado de busca: As plantas de drogas parecem visíveis da janela do apartamento, indicando que a produção de drogas está em andamento. O proprietário do apartamento recusou-se a abrir a porta para os policiais."</em></p>' WHERE `category_id` = 8 AND `title` = 'Warrant Structure' AND `content` = '<p>For a warrant to be reason enough to arrest someone and be classed as "valid", you need to provide an overview of the situation including evidence and weapons used (if any). Warrants only saying "Tried to run the uber driver over" will not be classed as "valid" or be enough to arrest someone for, as it does not give an overview of the situation nor does it tell us what kind of evidence was present at the time. It is also important to specify if it is a search warrant or if it is an arrest warrant.</p><p>A good example of an arrest warrant is: <em>"Arrest Warrant: Shot and killed the civilian during the armed robbery at 24/7 Sandy with an M9 Beretta. Several witnesses including police officers witnessed the situation. Evidence found on the scene."</em></p><p>A good example of a search warrant is: <em>"Search Warrant: Drug plants appear to be visible from the apartment window, indicating production of drugs is ongoing. Owner of the apartment refused to open the door for Officers."</em></p>';
UPDATE `mdt_sop_sections` SET `title` = 'Botão de pânico e comando de cena', `content` = '<p><strong>Botão de Pânico:</strong> O Botão de Pânico só deve ser pressionado quando houver uma preocupação urgente com a segurança pessoal sua ou de um colega, que requer assistência imediata.</p><ul><li><strong>Todas as Unidades devem responder a 10-99 Cenas. Os supervisores podem cancelar se não forem necessárias mais unidades no local.</strong></li></ul><p><strong>Comando de cena:</strong> O primeiro sargento ou superior no local será considerado como Comando de cena. Somente o comando de cena pode eliminar unidades da cena ativa, independentemente da classificação. O Comando de Cena Ativo aconselhará os policiais sobre o que fazer. <strong>Os assistentes de treinamento de campo podem assumir o comando de cena se não houver nenhum supervisor ativo em serviço.</strong></p>' WHERE `category_id` = 8 AND `title` = 'Panic Button and Scene Command' AND `content` = '<p><strong>Panic Button:</strong> The Panic Button is only to be pressed when there is an urgent concern for the personal safety of you or a colleague, which requires immediate assistance.</p><ul><li><strong>All Units must respond to 10-99 Scenes. Supervisors can call-off if no more units needed on the scene.</strong></li></ul><p><strong>Scene Command:</strong> First Sergeant or higher on the scene will be considered as Scene Command. Only Scene Command can clear off Units from the Active Scene regardless of Rank. Active Scene Command will advise officers on what to do. <strong>Field Training Assistants can take Scene Command if there is no Active Supervisor on Duty.</strong></p>';
UPDATE `mdt_sop_sections` SET `title` = 'Paradas de trânsito', `content` = '<p>No momento de qualquer parada de trânsito, ela é e será conhecida como cena e será tratada como tal. Embora um policial tenha qualquer pessoa sob investigação por excesso de velocidade, equipamentos inoperantes e veículos considerados impróprios para as estradas, todos os suspeitos serão atualmente DETIDOS (<strong>eles não precisam estar algemados, eles podem estar em seu veículo</strong>) durante a parada de trânsito. Eles não podem sair do local, mas podem chamar um advogado com antecedência se sentirem necessidade de fazê-lo. Em nenhum momento durante uma parada de trânsito deve ser utilizado o uso de força letal, a menos que um policial tema por sua vida. Menos que letal é sempre permitido se a situação surgir.</p><p>Durante uma parada de trânsito, se comandos de policiais forem dados ao suspeito ou acusado e após múltiplas tentativas o suspeito se recusar a obedecer, então várias etapas de força menos que letal são permitidas. O uso desta força é determinado pelo chefe do departamento. O uso de força letal não é permitido e resultará na remoção do policial ou em ação disciplinar.</p>' WHERE `category_id` = 8 AND `title` = 'Traffic Stops' AND `content` = '<p>At the time of any traffic stop, it is and shall be known as a scene and will be treated as such. While a police officer has any said person under investigation for speeding, inoperable equipment and vehicles deemed unfit for the roadways, all suspects will currently at that time be DETAINED (<strong>they do not have to be in handcuffs, they can be in their vehicle</strong>) during the traffic stop. They may not leave the scene, but may call a lawyer ahead of time if they feel the need to do so. At no point during a traffic stop should the use of deadly force be used unless an officer fears for his life. Less than lethal is always permitted if the situation arises.</p><p>During a traffic stop, if commands by law enforcement officers are given to the suspect or the accused and after multiple attempts the suspect refuses to comply, then various steps of less than lethal force are permitted. The use of this force is determined by the department head. Use of deadly force is not permitted and will result in the removal of the officer or disciplinary action.</p>';
UPDATE `mdt_sop_sections` SET `title` = 'Limites de velocidade e roubos', `content` = '<p><strong>Limites de velocidade:</strong></p><ul><li>Limites da cidade - 40 MPH</li><li>Rodovias / fora da cidade - 80 MPH</li></ul><p><strong>Máximo de oficiais permitidos por Roubo:</strong></p><ul><li>Assalto ao cassino: 4</li><li>Assalto no Pacífico: 5</li><li>Assalto a joias: 3</li><li>Fleeca Roubo: 4</li><li>Assalto a casa: 2</li><li>Assalto a loja: 3</li><li>Assalto a trem: 4</li><li>Assalto a caminhão: 3</li><li>Ativo 10-80s: 3 (carros)</li></ul>' WHERE `category_id` = 8 AND `title` = 'Speed Limits and Robberies' AND `content` = '<p><strong>Speed Limits:</strong></p><ul><li>City Limits - 40 MPH</li><li>Highways / Out-of-City - 80 MPH</li></ul><p><strong>Maximum Officers Allowed Per Robbery:</strong></p><ul><li>Casino Heist: 4</li><li>Pacific Robbery: 5</li><li>Jewelry Robbery: 3</li><li>Fleeca Robbery: 4</li><li>House Robbery: 2</li><li>Store Robbery: 3</li><li>Train Robbery: 4</li><li>Truck Robbery: 3</li><li>Active 10-80s: 3 (cars)</li></ul>';
UPDATE `mdt_sop_sections` SET `title` = 'Ar Um', `content` = '<p>Para um oficial ser certificado Air One, ele deve ser treinado e liberado por um FTI (Field Training Instructor). Somente um FTI do Departamento certificado pela Air One pode autorizar outros a serem certificados. Para obter a certificação Air One, seu instrutor de treinamento o guiará pelo curso de treinamento Air One, onde você deverá mostrar ao instrutor sua habilidade de voar e usar o Air One. Você só será aprovado se mostrar ao seu instrutor que está pronto. Você também aprenderá a maneira correta de usar o Air One.</p><p><strong>Regras:</strong></p><ul><li>O Air One só pode ficar desligado por 30 minutos antes de ter que voltar ao MRPD para reabastecer.</li><li>Deve haver um tempo de reabastecimento de 3 a 5 minutos antes que o Air One possa voltar ao ar ou reconecte-se a uma situação ativa.</li><li>Só pode lançar pessoas se a área for segura (o que significa que ninguém está atirando no Air One).</li></ul>' WHERE `category_id` = 8 AND `title` = 'Air One' AND `content` = '<p>For an officer to be Air One certified, one must be trained and cleared by a FTI (Field Training Instructor). Only a Department FTI who is Air One certified may clear others to be certified. To be cleared for Air One certification your training instructor will take you through the Air One training course where you will have to show your instructor your ability to fly and use Air One. You will only pass if you have shown your instructor that you are ready. You will also be taught the correct way to use Air One.</p><p><strong>Rules:</strong></p><ul><li>Air One can only be out for 30 minutes before having to go back to MRPD to refuel.</li><li>There must be a 3-5 minute refuel time before Air One can get back into the air or reattach back to an active situation.</li><li>Can only airdrop people off if the area is safe (meaning no one is shooting at Air One).</li></ul>';
UPDATE `mdt_sop_sections` SET `title` = 'Política de Uso da Força', `content` = '<p>Os agentes da lei podem usar qualquer quantidade de força no desempenho de suas funções, desde que seja razoável e justificável.</p><ul><li><strong>Uma arma de fogo só pode ser usada quando houver um perigo claro e presente à vida e outros métodos não letais forem inadequados ou falharem.</strong></li><li><strong>As armas de fogo nunca devem ser usado para apreender um suspeito em fuga, a menos que justificado no ponto acima.</strong></li><li><strong>Tiro(s) de advertência nunca devem ser disparados.</strong></li><li><strong>Só deve disparar sua arma de fogo se você tiver uma linha de visão desobstruída e for seguro fazê-lo.</strong> (NÃO FAÇA FOGO CRUZADO AOS OFICIAIS)</li><li><strong>Oficiais que usam força excessiva no desempenho de suas funções sem uma razão razoável e justificável podem levar a ação disciplinar.</strong></li></ul>' WHERE `category_id` = 9 AND `title` = 'Use of Force Policy' AND `content` = '<p>Law enforcement officers may use any amount of force in the execution of their duties provided that it is reasonable and justifiable.</p><ul><li><strong>A firearm may only be used when there is a clear and present danger to life and other non-lethal methods are inappropriate or have failed.</strong></li><li><strong>Firearms should never be used to apprehend a fleeing suspect unless justified in the point above.</strong></li><li><strong>Warning shot(s) should never be fired.</strong></li><li><strong>Should only be discharging your firearm if you have a clear line of sight and it is safe to do so.</strong> (DO NOT CROSSFIRE FELLOW OFFICERS)</li><li><strong>Officers that use excessive force in the execution of their duties without a reasonable and justifiable reason may lead to disciplinary action.</strong></li></ul>';
UPDATE `mdt_sop_sections` SET `title` = 'Diretrizes de Força Mortal', `content` = '<p><strong>(a) Uso de força letal:</strong> Força letal significa força usada contra outro indivíduo, que pode causar lesões corporais graves ou morte ao indivíduo em questão. O uso de força letal pode ser usado se uma ou mais das seguintes circunstâncias existirem:</p><p><strong>1 - Autodefesa:</strong> Quando a força letal parece razoavelmente necessária para proteger um policial que razoavelmente acredita que está em perigo iminente de morte ou lesão corporal grave.</p><p><strong>2 - Ofensas Graves:</strong> Quando força letal parece ser razoável e objectivamente necessária para proteger o público em geral de uma infracção grave. Exemplos: O sujeito em questão está dirigindo de forma imprudente a ponto de representar uma ameaça iminente ao público em geral ou aos oficiais. Ou o sujeito está atualmente armado com uma arma de fogo e os policiais acreditam que, sem qualquer dúvida, o sujeito a usará.</p><p><strong>3 - Pneus:</strong> Os policiais devem mirar nos pneus de um veículo quando for necessário atirar em um veículo que dirige de forma imprudente onde os ocupantes são conhecidos por estarem armados ou são um perigo para o público. Depois que os pneus forem estourados, os policiais devem parar de atirar no veículo.</p><p><strong>4 - Um aviso:</strong> "POLÍCIA PARE" ou "POLÍCIA, PARE OU VOCÊ SERÁ BALEADO" geralmente deve ser dado, se possível, antes que o policial dispare sua arma de fogo.</p><p><strong>5 - Veículos:</strong> Os veículos geralmente não devem ser usados como arma, a menos que este seja o último recurso do policial.</p>' WHERE `category_id` = 9 AND `title` = 'Deadly Force Guidelines' AND `content` = '<p><strong>(a) Use of Deadly Force:</strong> Deadly force means force that is used against another individual, that is likely to cause serious bodily harm or death to the individual in question. The Use of Deadly force may be used if one or more of the following circumstances exists:</p><p><strong>1 - Self Defence:</strong> When deadly force reasonably appears to be necessary to protect an officer who reasonably believes himself or herself is in imminent danger of death or serious bodily harm.</p><p><strong>2 - Serious Offences:</strong> When deadly force reasonably and objectively appears to be necessary to protect the general public from a serious offense. Examples: The subject in question is driving reckless to the point where it is posing an imminent threat to the general public or officers. Or the subject is currently armed with a firearm and the officers believe that without any doubt, the subject will use it.</p><p><strong>3 - Tires:</strong> Officers should aim for the tires of a vehicle when it is necessary to shoot a recklessly driving vehicle where the occupants are known to be armed or they are a danger to the public. Once the tires have been popped, officers should stop shooting the vehicle.</p><p><strong>4 - A Warning:</strong> "POLICE STOP" or "POLICE, STOP OR YOU WILL BE SHOT" should generally be given if possible before the officer discharges his firearm.</p><p><strong>5 - Vehicles:</strong> Vehicles should generally not be used as a weapon unless this is the officer''s last resort.</p>';
UPDATE `mdt_sop_sections` SET `title` = 'Fases de Treinamento', `content` = '<p>Quando você se torna um Oficial de Aplicação da Lei dentro do departamento, você deve passar por 3 etapas de Treinamento de Campo. Cada estagiário será designado com um Oficial de Treinamento de Campo ou Assistente de Treinamento de Campo. Os estagiários que passarem nas 3 etapas do Treinamento de Campo terão a capacidade de Patrulhar Sozinhos. Até então, eles só podem patrulhar com oficiais de patrulha ou com o FTO designado.</p>' WHERE `category_id` = 10 AND `title` = 'Training Phases' AND `content` = '<p>When you become a Law Enforcement Officer within the department, you must go through 3 stages of Field Training. Each trainee will be assigned with a Field Training Officer or Field Training Assistant. Trainees who pass the 3 stages of Field Training will have the ability to Patrol Alone. Until then, they can only Patrol with Patrol Officers or their assigned FTO.</p>';
UPDATE `mdt_sop_sections` SET `title` = 'Direitos Miranda', `content` = '<p><em> "Você tem o direito de permanecer em silêncio, qualquer coisa que você diga ou faça pode ser usada contra você em um tribunal, você tem direito a um advogado. Se não puder pagar um, um será nomeado para você pelo estado. Você entende os direitos que foram lidos para você? Com ​​esses direitos em mente, deseja falar comigo?"</em></p>' WHERE `category_id` = 10 AND `title` = 'Miranda Rights' AND `content` = '<p><em>"You have the right to remain silent, anything you say or do can be used against you in a court of law, you have the right to an attorney. If you can not afford one, one will be appointed to you by the state. Do you understand the rights that have been read to you? With these rights in mind, do you wish to speak to me?"</em></p>';
UPDATE `mdt_sop_sections` SET `title` = 'Advogado Ping', `content` = '<p>Quando você prende alguém, essa pessoa tem direito à presença de um advogado. Faça ping para um advogado no Discord na categoria DOJ> #lawyer-ping. Aguarde uma resposta ou a chegada de um advogado. Se ninguém chegar após 10 minutos, prossiga com a prisão.</p>' WHERE `category_id` = 10 AND `title` = 'Lawyer Ping' AND `content` = '<p>When you arrest someone they have the right to a lawyer present. Ping a lawyer in Discord on the DOJ Category > #lawyer-ping. Wait for an answer or for a lawyer to arrive. If no one has arrived after 10 minutes proceed with the arrest.</p>';
UPDATE `mdt_sop_sections` SET `title` = 'Veículos de polícia', `content` = 'Os carros <p>PD (aqueles que você encontra na garagem) serão distribuídos como carros pessoais. Você pode estacioná-los em suas garagens e fazer atualizações em seus cruzadores pessoais.</p><ul><li>Você não pode alterar as cores ou pinturas.</li><li>Você pode instalar atualizações para tornar seu carro mais rápido com qualquer um dos mecânicos da cidade.</li></ul>' WHERE `category_id` = 11 AND `title` = 'PD Vehicles' AND `content` = '<p>PD cars (the ones you find in the garage) will be given out as personal cars. You can park them in your garages and do upgrades to your personal cruisers.</p><ul><li>You may not change the colors or liveries.</li><li>You may install upgrades to make your car faster with any of the mechanics in town.</li></ul>';
UPDATE `mdt_sop_sections` SET `title` = 'Unidade K9', `content` = '<p><em>Trabalho em andamento</em></p>' WHERE `category_id` = 11 AND `title` = 'K9 Unit' AND `content` = '<p><em>Work in Progress</em></p>';

-- Keep report templates isolated by MDT domain.
UPDATE `mdt_report_templates`
SET `job_type` = 'leo'
WHERE (`job_type` IS NULL OR `job_type` = 'all')
  AND `type` IN ('Incident Report', 'Traffic Report', 'Investigation Report', 'Arrest Report', 'Evidence Report', 'Relatório de incidente', 'Relatório de tráfego', 'Relatório de Investigação', 'Relatório de prisão', 'Relatório de evidências');

INSERT INTO `mdt_report_templates` (`name`, `type`, `content`, `job_type`)
SELECT 'Avaliação Médica Geral', 'Medical Report', '<h2>Avaliação do paciente</h2><p><strong>Queixa principal:</strong> [QUEIXA]</p><p><strong>Sinais vitais:</strong> [SINAIS VITAIS]</p><h2>Tratamento e Destino</h2><p>[TRATAMENTO / TRANSPORTE]</p>', 'ems'
WHERE NOT EXISTS (SELECT 1 FROM `mdt_report_templates` WHERE `job_type` = 'ems' AND `type` = 'Medical Report');
INSERT INTO `mdt_report_templates` (`name`, `type`, `content`, `job_type`)
SELECT 'Atendimento de Trauma', 'Trauma Report', '<h2>Avaliação do trauma</h2><p><strong>Mecanismo da lesão:</strong> [MECANISMO]</p><p><strong>Lesões:</strong> [LESÕES]</p><h2>Intervenções</h2><p>[INTERVENÇÕES / TRANSPORTE]</p>', 'ems'
WHERE NOT EXISTS (SELECT 1 FROM `mdt_report_templates` WHERE `job_type` = 'ems' AND `type` = 'Trauma Report');
INSERT INTO `mdt_report_templates` (`name`, `type`, `content`, `job_type`)
SELECT 'Atendimento de Overdose', 'Overdose Report', '<h2>Avaliação da overdose</h2><p><strong>Substância suspeita:</strong> [SUBSTÂNCIA]</p><p><strong>Condição inicial:</strong> [CONDIÇÃO]</p><h2>Tratamento e Resultado</h2><p>[TRATAMENTO / RESPOSTA / TRANSPORTE]</p>', 'ems'
WHERE NOT EXISTS (SELECT 1 FROM `mdt_report_templates` WHERE `job_type` = 'ems' AND `type` = 'Overdose Report');
INSERT INTO `mdt_report_templates` (`name`, `type`, `content`, `job_type`)
SELECT 'Avaliação Psiquiátrica', 'Psychiatric Report', '<h2>Avaliação de saúde mental</h2><p><strong>Apresentação:</strong> [APRESENTAÇÃO]</p><p><strong>Avaliação de risco:</strong> [RISCO]</p><h2>Intervenção e Destino</h2><p>[INTERVENÇÃO / DESTINO]</p>', 'ems'
WHERE NOT EXISTS (SELECT 1 FROM `mdt_report_templates` WHERE `job_type` = 'ems' AND `type` = 'Psychiatric Report');
INSERT INTO `mdt_report_templates` (`name`, `type`, `content`, `job_type`)
SELECT 'Atendimento com Múltiplas Vítimas', 'Mass Casualty Report', '<h2>Visão geral do incidente</h2><p><strong>Local:</strong> [LOCAL]</p><p><strong>Resumo da triagem:</strong> [QUANTIDADES POR TRIAGEM]</p><h2>Recursos e Transporte</h2><p>[RECURSOS / DESTINOS]</p>', 'ems'
WHERE NOT EXISTS (SELECT 1 FROM `mdt_report_templates` WHERE `job_type` = 'ems' AND `type` = 'Mass Casualty Report');

INSERT INTO `mdt_report_templates` (`name`, `type`, `content`, `job_type`)
SELECT 'Petição Judicial Padrão', 'Court Filing', '<h2>Petição judicial</h2><p><strong>Processo:</strong> [PROCESSO Nº]</p><p>[DETALHES DA PETIÇÃO]</p>', 'doj'
WHERE NOT EXISTS (SELECT 1 FROM `mdt_report_templates` WHERE `job_type` = 'doj' AND `type` = 'Court Filing');
INSERT INTO `mdt_report_templates` (`name`, `type`, `content`, `job_type`)
SELECT 'Memorial Jurídico Padrão', 'Legal Brief', '<h2>Memorial jurídico</h2><p><strong>Matéria:</strong> [MATÉRIA]</p><p>[ARGUMENTOS E FUNDAMENTOS]</p>', 'doj'
WHERE NOT EXISTS (SELECT 1 FROM `mdt_report_templates` WHERE `job_type` = 'doj' AND `type` = 'Legal Brief');
