WHERE NOT EXISTS (SELECT 1 FROM `mdt_report_templates` WHERE `job_type` = 'doj' AND `type` = 'Plea Agreement');
INSERT INTO `mdt_report_templates` (`name`, `type`, `content`, `job_type`)
