-- Repair functional report type identifiers translated by earlier pt-BR migrations
UPDATE `mdt_report_templates` SET `type` = 'Incident Report' WHERE `type` = 'Relatório de incidente';
UPDATE `mdt_report_templates` SET `type` = 'Traffic Report' WHERE `type` = 'Relatório de tráfego';
UPDATE `mdt_report_templates` SET `type` = 'Investigation Report' WHERE `type` = 'Relatório de Investigação';
UPDATE `mdt_report_templates` SET `type` = 'Arrest Report' WHERE `type` = 'Relatório de prisão';
UPDATE `mdt_report_templates` SET `type` = 'Evidence Report' WHERE `type` = 'Relatório de evidências';

COMMIT;
